package com.bank.strategy.strategy;

import com.bank.strategy.model.Event;
import java.util.concurrent.atomic.AtomicInteger;

// No key: spread evenly. Mirrors sticky/round-robin for keyless records.
public class RoundRobinStrategy implements PartitionStrategy {
    private final AtomicInteger counter = new AtomicInteger();

    @Override public int choose(Event event, int numPartitions) {
        return Math.floorMod(counter.getAndIncrement(), numPartitions);
    }
    @Override public String name() { return "ROUND_ROBIN (no key)"; }
}
