package com.bank.strategy.strategy;

import com.bank.strategy.model.Event;

// Keyed: same account id always maps to same partition -> per-account ordering.
public class HashKeyStrategy implements PartitionStrategy {
    @Override public int choose(Event event, int numPartitions) {
        String key = event.getAccountId();
        if (key == null) return 0;
        return (key.hashCode() & 0x7fffffff) % numPartitions;
    }
    @Override public String name() { return "HASH_OF_KEY (per-account order)"; }
}
