package com.bank.strategy.strategy;

import com.bank.strategy.model.Event;

// Custom business logic: premium accounts routed to dedicated partitions 10,11.
public class TierPartitioner implements PartitionStrategy {
    private final int[] premiumPartitions = {10, 11};

    @Override public int choose(Event event, int numPartitions) {
        if (event.isPremium()) {
            String key = event.getAccountId() == null ? "P" : event.getAccountId();
            return premiumPartitions[(key.hashCode() & 0x7fffffff) % premiumPartitions.length];
        }
        // non-premium: normal hash but only over partitions 0..9
        int retail = 10;
        String key = event.getAccountId() == null ? "R" : event.getAccountId();
        return (key.hashCode() & 0x7fffffff) % retail;
    }
    @Override public String name() { return "CUSTOM TierPartitioner (premium->10,11)"; }
}
