package com.bank.strategy;

import com.bank.strategy.model.Event;
import com.bank.strategy.strategy.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class StrategyDemo {
    private static final Logger log = Logger.getLogger(StrategyDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        int partitions = 12;
        List<Event> events = List.of(
            new Event("AUDIT", null, false, BigDecimal.ZERO),
            new Event("AUDIT", null, false, BigDecimal.ZERO),
            new Event("TRANSFER", "SAV2001", false, new BigDecimal("50000")),
            new Event("TRANSFER", "SAV2001", false, new BigDecimal("20000")),
            new Event("TRANSFER", "CUR3001", true, new BigDecimal("1000000")));

        for (PartitionStrategy s : List.of(
                new RoundRobinStrategy(), new HashKeyStrategy(), new TierPartitioner())) {
            log.info("Strategy: " + s.name());
            for (Event e : events) {
                int p = s.choose(e, partitions);
                log.info(() -> "  " + e.getType() + " acc=" + e.getAccountId()
                        + " premium=" + e.isPremium() + " -> partition " + p);
            }
        }
        log.info("Note: SAV2001's two transfers share one partition under HASH_OF_KEY (ordered).");
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$-7s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
